"""Short absence notices to send home to parents."""

from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed


def _check_owner(student: Student, marks: list) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id} given "
                f"for {student.student_id}"
            )


def _compose(student: Student, days: list) -> str:
    count = len(days)
    word = "day" if count == 1 else "days"
    listed = ", ".join(day.isoformat() for day in days)
    return (
        f"{student.first_name} {student.last_name} "
        f"missed {count} {word}: {listed}."
    )


# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    items = list(marks)
    _check_owner(student, items)
    days = days_missed(items)
    if not days:
        raise ProjectError("no absences to write about")
    return _compose(student, days)
